// Character feature chronology, choice-bearing feats and death saves (4.7).
function featLedger47(){const p=playState(),x=c(),s=selections();if(!Array.isArray(p.featureGrants47))p.featureGrants47=[];if(!p.featureMigration47){p.featureMigration47=true;const history=[...(p.levelHistory||[]),x];for(let i=1;i<history.length;i++){const before=history[i-1],after=history[i],cls=after.classes.find(a=>a.level>(before.classes.find(b=>b.name===a.name)?.level||0));if(!cls)continue;for(const id of after.bookChoices?.feats||[])if(!(before.bookChoices?.feats||[]).includes(id))p.featureGrants47.push({uid:crypto.randomUUID(),type:'feat',featId:id,cls:cls.name,level:cls.level,totalLevel:after.level,choices:{},legacy:true});}}for(const id of s.feats){if(levelDraft?.recording47&&id===levelDraft.feat)continue;if(p.featureGrants47.some(g=>g.featId===id))continue;const feat=getBook(id);if(!feat)continue;const origin=s.originFeat||getBook(s.background)?.feat||'',human=x.creationWizard?.extra?.humanFeat===id;const isOrigin=human||origin.includes(feat.name);const grant={uid:crypto.randomUUID(),type:'feat',featId:id,cls:isOrigin?x.classes[0].name:null,level:isOrigin?1:null,totalLevel:isOrigin?1:null,origin:isOrigin,legacy:true,choices:{}};if(feat.name==='Magic Initiate'){const d=x.creationWizard,magic=origin.match(/Cleric|Druid|Wizard/)?.[0]||x.customBackground?.magicClass;if(magic)grant.choices.magicClass=magic;if(d?.extra?.mi0){Object.assign(grant.choices,{cast:String(d.extra.miAttr??3),cantrip0:d.extra.mi0,cantrip1:d.extra.mi1,spell:d.extra.mi2});grant.choicesReady=true;}}p.featureGrants47.push(grant);}return p.featureGrants47;}
