const errorBefore47=featError45;featError45=function(feat,x=c(),next=x.level+1){if(!feat)return 'Escolha um talento.';let error=errorBefore47(feat,x,next);const repeat=feat.name==='Magic Initiate'||feat.name==='Elemental Adept'||feat.name==='Ability Score Improvement'||feat.name==='Skilled';if(error==='Este talento já está na ficha.'&&repeat)error='';if(error)return error;if(feat.name==='Magic Initiate'){if(!unusedMagicLists47(feat).length)return 'Todas as três listas já foram escolhidas.';}else if(feat.name==='Elemental Adept'){if(usedFeatChoices47(feat,'element').length>=5)return 'Todos os tipos de dano já foram escolhidos.';}else if(featOwned47(feat)&&!repeat)return 'Este talento já está na ficha.';if(feat.category==='Fighting Style'&&!x.classes.some(p=>['Guerreiro','Paladino','Patrulheiro'].includes(p.name)&&(p.name==='Guerreiro'||p.level>=2)))return 'Requer a característica Estilo de Luta.';if(feat.name==='Moderately Armored'&&!/Leves|leves/.test(proficiencySummary()))return 'Requer treinamento com armaduras leves.';return '';};
