const commitLevelBefore47=commitLevelUp;commitLevelUp=function(){const d=levelDraft,x=c();if(!d||d.committed)return;const error=levelUpError(x,d);if(error)return toast(error);featLedger47();if(d.asi==='feat'&&!d.featChoicesReady47){beginFeatDetails47();return;}if((d.subclass||selections().subclasses[d.cls])==='518'&&!d.land47&&!playState().land47){evoDialog45.innerHTML=`<h2>Círculo da Terra</h2>${select45('Tipo de terreno','land-choice47',Object.keys(PROGRESSION47.Druida.subclasses['518'].landSpells).map(v=>[v,LAND_NAMES47[v]]),'Arid')}<button class="primary" onclick="levelDraft.land47=document.querySelector('#land-choice47').value;evoDialog45.close();commitLevelUp()">Confirmar terreno</button>`;if(!evoDialog45.open)evoDialog45.showModal();enhanceSelects(evoDialog45);return;}
const before=x.level,clsLevel=nextClassLevel(d.cls);d.recording47=true;try{commitLevelBefore47();}finally{d.recording47=false;}if(x.level!==before+1||d.recorded47)return;d.recorded47=true;const base={uid:crypto.randomUUID(),cls:d.cls,level:clsLevel,totalLevel:x.level};if(d.asi==='feat'){const g={...base,type:'feat',featId:d.feat,choices:{...(d.featChoices47||{})},choicesReady:true,attr:d.featAttr,boost:d.featAttr!==undefined?{[d.featAttr]:featBoost45(getBook(d.feat))?.asi&&d.featMode==='2'?2:1,...(d.featAttr2!==undefined?{[d.featAttr2]:1}:{})}:null};playState().featureGrants47.push(g);applyFeatChoices47(g);}else if(['2','1+1'].includes(d.asi))playState().featureGrants47.push({...base,type:'asi',boost:d.asi==='2'?{[d.a]:2}:{[d.a]:1,[d.b]:1}});if(d.land47)playState().land47=d.land47;save();render();};
