function formatRule47(text){let t=String(text||'').replace(/\u00ad\s*/g,'').replace(/(?<=\w)-\n(?=\w)/g,'').replace(/^.*CHAPTER\s*\d.*$/gim,'').trim();const lines=t.split('\n');let paragraphs=[],current='';for(const l of lines){const line=l.trim();if(!line){if(current){paragraphs.push(current);current='';}continue;}if(/^[\W_\dA-Z]{1,10}$/.test(line))continue;if(/^[A-Z][A-Za-z’' -]{2,45}\. /.test(line)&&current){paragraphs.push(current);current='';}current+=(current?' ':'')+line;}if(current)paragraphs.push(current);return paragraphs.flatMap(p=>{if(p.length<650)return [p];const chunks=p.match(/[^.!?]+[.!?]+(?:[”’'"])?|[^.!?]+$/g)||[p];let groups=[],str='';for(const sentence of chunks){str+=sentence;if(str.length>360){groups.push(str);str='';}}if(str)groups.push(str);return groups;}).map(p=>`<p>${esc(p).replace(/^([A-Z][A-Za-z’' -]{2,45})\. /,'<strong class="rule-benefit47">$1.</strong> ').replace(/\b(Bonus Action|Reaction|Long Rest|Short Rest|Advantage|Disadvantage|Concentration)\b/g,'<b class="rule-term47">$1</b>')}</p>`).join('');}
