function openCharacterFeature47(index){const r=progressionRows47()[index];if(!r)return;if(r.type==='subclass'&&r.subId)return openSubclass47(r.subId);const feat=r.type==='feat'?getBook(r.grant.featId):null;const text=feat?.text||(r.feature?featureText47(r.feature):'');let html=`<div class="feature-dialog-ribbon">${esc(r.cls)} ${r.level??'· nível não registrado'}${r.subId?' · '+esc(getBook(r.subId)?.name):''}</div>${r.grant?grantSummary47(r.grant):''}<div class="feature-rule47">${formatRule47(text)}</div>`;if(r.grant&&!Number.isInteger(r.grant.level))html+=`<button onclick="openAcquisition47('${r.grant.uid}')">Registrar nível de aquisição</button>`;if(r.grant&&feat&&featTasks47(feat,r.grant.choices||{},null).length&&!r.grant.choicesReady)html+=`<button class="primary" onclick="beginFeatDetails47(liveFeatGrants47().find(g=>g.uid==='${r.grant.uid}'))">Concluir escolhas deste talento</button>`;if(r.subId){if(/Spells$/.test(r.feature?.name||''))html+=spellTable47(PROGRESSION47[r.cls].subclasses[r.subId]);html+=tablesView47(r.subId);html+=`<button onclick="openSubclass47('${r.subId}')">Ver subclasse completa</button>`;}openPlayDialog(r.name,html);}
