function tablesView47(id){const sub=Object.values(PROGRESSION47).flatMap(d=>Object.values(d.subclasses)).find(s=>s.id===id);return (sub?.tables||[]).map((t,i)=>`<section class="feature-roll-table47"><h3>${esc(t.name)}</h3><button class="primary" onclick="rollFeatureTable47('${id}',${i})">Rolar 1d${t.sides}</button><div class="feature-table-scroll47"><table><thead><tr><th>1d${t.sides}</th><th>Efeito</th></tr></thead><tbody>${t.rows.map(r=>`<tr><th>${r.min}${r.max!==r.min?'–'+r.max:''}</th><td>${esc(r.text.replace(/\s+/g,' '))}</td></tr>`).join('')}</tbody></table></div></section>`).join('');}
