const combatBefore47=combat;combat=function(){const box=document.createElement('div');box.innerHTML=combatBefore47();box.querySelectorAll('section.card').forEach(card=>{const title=card.querySelector('h2,h3')?.textContent.trim()||'';if(['Características por nível','Talentos do catálogo','Recursos'].includes(title)||card.querySelector('textarea[oninput*="equipment"]'))card.remove();});const defense=[...box.querySelectorAll('section.card')].find(card=>card.querySelector('h3')?.textContent==='Defesa automática');const old=box.querySelector('input[onchange*="deathSuccess"]')?.closest('section.card');if(defense){defense.classList.add('defense47');defense.querySelector('h3').textContent='Defesa e Salvaguardas contra Morte';const summary=document.createElement('div');summary.className='defense-summary47';summary.innerHTML=`<span>CLASSE DE ARMADURA</span><strong>${c().ac}</strong>`;defense.querySelector('h3').after(summary);if(old){for(const child of [...old.children]){if(child.tagName==='H3')break;defense.append(child);}old.remove();}defense.insertAdjacentHTML('beforeend',deathSavesView47());}return box.innerHTML;};
const overviewBefore47=overview;overview=function(){const box=document.createElement('div');box.innerHTML=overviewBefore47();const history=box.querySelector('.history-card')||[...box.querySelectorAll('section.card')].find(e=>e.querySelector('h3')?.textContent==='História'),progress=box.querySelector('.progression-details');const anchor=history||progress;if(anchor)anchor.insertAdjacentHTML('beforebegin',characterFeatures47());else box.insertAdjacentHTML('beforeend',characterFeatures47());return box.innerHTML;};
const levelRenderBefore47=renderLevelUp;renderLevelUp=function(){levelRenderBefore47();const d=levelDraft,n=nextClassLevel(d.cls),data=PROGRESSION47[d.cls],sub=data?.subclasses[d.subclass||selections().subclasses[d.cls]],root=document.querySelector('#levelup-body');const h=[...root.querySelectorAll('h3')].find(h=>h.textContent==='Novas características');if(h){let node=h.nextElementSibling;while(node&&node.tagName==='P'&&!node.classList.contains('muted')){const next=node.nextElementSibling;node.remove();node=next;}h.insertAdjacentHTML('afterend',`<div class="level-feature-preview47">${[...(data?.base||[]),...(sub?.features||[])].filter(f=>f.level===n).map(f=>`<p>✦ ${esc(f.name)}</p>`).join('')||'<p>Progressão dos recursos da classe.</p>'}</div>`);}};
function deathSavesView47(){const x=c(),dead=x.deathFail>=3,stable=x.deathSuccess>=3;return `<div class="death-saves47"><h3>Salvaguardas contra Morte</h3><div class="death-track47">${[['Sucessos','success',x.deathSuccess],['Falhas','failure',x.deathFail]].map(([name,kind,n])=>`<div class="death-row47"><span>${name}</span><div>${[1,2,3].map(i=>`<span class="death-mark47 ${kind} ${n>=i?'marked':''}" role="checkbox" aria-disabled="true" aria-label="${name} ${i}" aria-checked="${n>=i}"><i></i></span>`).join('')}</div></div>`).join('')}</div><p class="death-state47" role="status">${dead?'Três falhas · personagem morto':stable?'Três sucessos · estabilizado':x.hp>0?'Disponível quando estiver com 0 PV':'Role 1d20 · 10 ou mais é um sucesso'}</p><button class="primary death-roll47" ${dead||stable||x.hp>0?'disabled':''} onclick="rollDeathSave47()">Salvaguarda Contra Morte</button><button class="death-reset47" aria-label="Limpar salvaguardas contra morte e restaurar cores" title="Limpar salvaguardas" onclick="resetDeath47()"><span>↺</span></button></div>`;}
function resetDeath47(){c().deathSuccess=0;c().deathFail=0;save();render();}
function rollDeathSave47(){const x=c();if(x.hp>0||x.deathFail>=3||x.deathSuccess>=3||diceIsRolling)return;let applied=false,natural=0;const charId=x.id;requestDice({rollKind:'save',label:'Salvaguarda Contra Morte',sides:20,count:1,bonus:0,damageRoll:true,deathRoll47:true,onNatural:n=>{natural=n;},apply:total=>{const n=natural;if(applied||c().id!==charId)return;applied=true;if(n===20){x.hp=1;x.deathSuccess=x.deathFail=0;}else if(n===1)x.deathFail=Math.min(3,(x.deathFail||0)+2);else if(total<10)x.deathFail=Math.min(3,(x.deathFail||0)+1);else x.deathSuccess=Math.min(3,(x.deathSuccess||0)+1);lastDeathOutcome47=x.deathFail>=3?'dead':n===20?'miracle':total>=10?'success':'failure';save();render();}});}
function omenSVG47(kind){if(kind==='failure'||kind==='dead')return `<svg viewBox="0 0 200 180" aria-hidden="true"><path d="M44 86C20 22 67 12 100 12s80 10 56 74l-12 22v31l-12 14H68l-12-14v-31Z" fill="#ded6c7" stroke="#6d4a4b" stroke-width="4"/><path d="M58 70q17-15 29 0l-4 25q-25 9-25-25Zm84 0q-17-15-29 0l4 25q25 9 25-25ZM100 91l-9 20h18Z" fill="${kind==='dead'?'#a90721':'#392a35'}"/><path d="M70 130h60m-45-10v25m15-25v25m15-25v25" stroke="#563e43" stroke-width="5"/>${kind==='dead'?'<path d="M64 77h15m42 0h15" stroke="#ff334b" stroke-width="5"/>':''}</svg>`;return `<svg viewBox="0 0 240 180" aria-hidden="true"><defs><linearGradient id="wings47" x2="0" y2="1"><stop stop-color="#fffde4"/><stop offset="1" stop-color="#bda263"/></linearGradient></defs><path d="M119 128C76 147 32 104 15 34c25 27 44 10 65 36 16 19 23 35 39 58ZM121 128c43 19 87-24 104-94-25 27-44 10-65 36-16 19-23 35-39 58Z" fill="url(#wings47)" stroke="#f8e9af" stroke-width="2"/><path d="M110 122 35 61m72 57L35 79m66 33L44 95m86 27 75-61m-72 57 72-39m-66 33 57-17" stroke="#9d874e" stroke-width="2"/><ellipse cx="120" cy="35" rx="27" ry="8" fill="none" stroke="#fff3a9" stroke-width="5"/><path d="m120 65 7 17 18 5-18 7-7 20-7-20-18-7 18-5Z" fill="#fffbd3"/></svg>`;}
