const resolveBefore47=resolveDice;resolveDice=function(mode){const req=pendingDice,result=resolveBefore47(mode);if(!req||!document.querySelector('#play-dialog').open)return result;const token=diceAnimationToken,charId=c().id,kind=lastDeathOutcome47;const delay=matchMedia('(prefers-reduced-motion: reduce)').matches?30:1720;setTimeout(()=>{if(token!==diceAnimationToken||c()?.id!==charId||!document.querySelector('#play-dialog').open)return;const body=document.querySelector('#play-body');if(req.table47){const row=req.table47.rows.find(r=>result>=r.min&&result<=r.max);if(row){const node=document.createElement('div');node.className='table-result47';node.setAttribute('role','status');node.innerHTML=`<h3>${esc(req.table47.name)} · ${result}</h3>${formatRule47(row.text)}<button onclick="openSubclass47('${req.tableSource47}')">Voltar à subclasse</button>`;body.append(node);}}
if(req.deathRoll47){body.querySelector('.reroll-hint')?.remove();body.insertAdjacentHTML('beforeend',`<p class="death-roll-summary47">Sucessos: ${c().deathSuccess}/3 · Falhas: ${c().deathFail}/3${kind==='miracle'?' · Recuperou 1 PV':kind==='dead'?' · Personagem morto':c().deathSuccess>=3?' · Estabilizado':''}</p>`);const node=document.createElement('div');node.className='death-omen47 '+kind;node.innerHTML=omenSVG47(kind)+`<span>${kind==='dead'?'A jornada silencia':kind==='miracle'?'Um novo fôlego · 1 PV':kind==='success'?'A vida resiste':'À beira do fim'}</span>`;body.append(node);setTimeout(()=>node.remove(),3200);}},delay);return result;};
const rerollBefore47=rerollLastDice;rerollLastDice=function(){if(lastDiceRoll?.req?.deathRoll47)return toast('Use o botão de Salvaguarda Contra Morte para o próximo teste.');return rerollBefore47();};
const renderBefore47=render;render=function(){if(c())featLedger47();renderBefore47();document.body.classList.toggle('character-dead47',!!c()&&c().deathFail>=3);};
