function featureKey410(r){return r.grant?.uid?'grant:'+r.grant.uid:JSON.stringify([r.type,r.cls,r.level,r.subId||'',r.name]);}
const progressionRowsBefore410=progressionRows47;progressionRows47=function(){const removed=playState().removedFeatureEntries410||[];return progressionRowsBefore410().filter(r=>!removed.includes(featureKey410(r)));};
function requestDeleteFeature410(index){const r=progressionRows47()[index];if(!r)return;const characterId=c().id,key=featureKey410(r);openPlayDialog('Excluir característica',`<p>Excluir <strong>${esc(r.name)}</strong> do quadro Características de Personagem?</p><button class="danger" id="confirm-feature-delete410">Excluir esta entrada</button><button onclick="document.querySelector('#play-dialog').close()">Cancelar</button>`);document.querySelector('#confirm-feature-delete410').onclick=()=>{if(c().id!==characterId)return;const p=playState();p.removedFeatureEntries410??=[];if(!p.removedFeatureEntries410.includes(key))p.removedFeatureEntries410.push(key);save();render();document.querySelector('#play-dialog').close();};}
(()=>{let hold=null,timer=null,suppress=null;const cancel=()=>{clearTimeout(timer);timer=null;hold=null;};document.addEventListener('pointerdown',e=>{if(e.button!==0||e.isPrimary===false)return;const row=e.target.closest?.('.feature-bar47[data-feature-index]');if(!row)return;cancel();hold={row,index:Number(row.dataset.featureIndex),character:c().id,x:e.clientX,y:e.clientY};timer=setTimeout(()=>{if(!hold||c().id!==hold.character){cancel();return;}const {row,index}=hold;suppress={row,until:Date.now()+1200};cancel();requestDeleteFeature410(index);hpTouchFeedback();},650);},true);document.addEventListener('pointermove',e=>{if(hold&&Math.hypot(e.clientX-hold.x,e.clientY-hold.y)>12)cancel();},true);for(const name of ['pointerup','pointercancel','blur'])window.addEventListener(name,cancel);document.addEventListener('click',e=>{if(suppress&&Date.now()<suppress.until&&suppress.row.contains(e.target)){e.preventDefault();e.stopImmediatePropagation();suppress=null;}},true);document.addEventListener('contextmenu',e=>{if(e.target.closest?.('.feature-bar47'))e.preventDefault();});})();

const SPECIES_TRAITS411={"659": [{"name": "Celestial Resistance", "text": "You have Resistance to Necrotic damage and Radiant damage."}, {"name": "Darkvision", "text": "You have Darkvision with a range of\n60 feet."}, {"name": "Healing Hands", "text": "As a Magic action, you touch a\ncreature and roll a number of d4s equal to your\nProficiency Bonus. The creature regains a number\nof Hit Points equal to the total rolled. Once you use\nthis trait, you can t use it again until you finish a\nLong Rest."}, {"name": "Light Bearer", "text": "You know the Light cantrip Charisma is your spellcasting ability for it."}, {"name": "Celestial Revelation", "text": "When you reach character\nlevel 3, you can transform as a Bonus Action using\none of the options below (choose the option each\ntime you transform). The transformation lasts for\n1 minute or until you end it (no action required).\nOnce you transform, you can’t do so again until you\nfinish a Long Rest.\nOnce on each of your turns before the transformation ends, you can deal extra damage to one target when you deal damage to it with an attack or a\nspell. The extra damage equals your Proficiency Bonus, and the extra damage’s type is either Necrotic\nfor Necrotic Shroud or Radiant for Heavenly Wings\nand Inner Radiance.\nHere are the transformation options:\nHeavenly Wings. Two spectral wings sprout from\nyour back temporarily. Until the transformation\nends, you have a Fly Speed equal to your Speed.\nInner Radiance. Searing light temporarily radiates\nfrom your eyes and mouth. For the duration, you\nshed Bright Light in a 10-foot radius and Dim\nLight for an additional 10 feet, and at the end of\neach of your turns, each creature within 10 feet\nof you takes Radiant damage equal to your Proficiency Bonus.\nNecrotic Shroud. Your eyes briefly become pools\nof darkness, and flightless wings sprout from your\nback temporarily. Creatures other than your allies\nwithin 10 feet ofyou must succeed on a Charisma\nsaving throw (DC 8 plus your Charisma modifier\nand Proficiency Bonus) or have the Frightened\ncondition until the end of your next turn."}], "660": [{"name": "Draconic Ancestry", "text": "Your lineage stems from a\ndragon progenitor. Choose the kind of dragon from\nthe Draconic Ancestors table. Your choice affects\nyour Breath Weapon and Damage Resistance traits\nas well as your appearance.\nDraconic Ancestors\nDragon Damage Type Dragon Damage Type\nBlack Acid Cold Fire\nBlue Lightning Green Poison\nBrass Fire Red Fire\nBronze Lightning Silver Cold\nCopper Ar-. White Cold"}, {"name": "Breath Weapon", "text": "When you take the Attack action\non your turn, you can replace one ofyour attacks\nwith an exhalation of magical energy in either a\n15-foot Cone or a 30-foot Line that is 5 feet wide\n(choose the shape each time). Each creature in that\narea must make a Dexterity saving throw (DC 8\nplus your Constitution modifier and Proficiency Bonus). On a failed save, a creature takes ldlO damage\nof the type determined by your Draconic Ancestry\ntrait. On a successful save, a creature takes half as\nmuch damage. This damage increases by ldlO when\nyou reach character levels 5 (2dl0), 11 (3dl0), and\n17 (4dl0).\nYou can use this Breath Weapon a number of\ntimes equal to your Proficiency Bonus, and you regain all expended uses when you finish a Long Rest."}, {"name": "Damage Resistance", "text": "You have Resistance to the\ndamage type determined by your Draconic Ancestry trait."}, {"name": "Darkvision", "text": "You have Darkvision with a range of\n60 feet."}, {"name": "Draconic Flight", "text": "When you reach character level\n5, you can channel draconic magic to give yourself\ntemporary flight. As a Bonus Action, you sprout\nspectral wings on your back that last for 10 minutes\nor until you retract the wings (no action required)\nor have the Incapacitated condition. During that\ntime, you have a Fly Speed equal to your Speed.\nYour wings appear to be made of the same energy\nas your Breath Weapon. Once you use this trait, you\ncan’t use it again until you finish a Long Rest."}], "661": [{"name": "Darkvision", "text": "You have Darkvision with a range of\n120 feet."}, {"name": "Dwarven Resilience", "text": "You have Resistance to Poison\ndamage. You also have Advantage on saving throws\nyou make to avoid or end the Poisoned condition."}, {"name": "Dwarven Toughness", "text": "Your Hit Point maximum\nincreases by 1, and it increases by 1 again whenever\nyou gain a level."}, {"name": "Stonecunning", "text": "As a Bonus Action, you gain Tremorsense with a range of 60 feet for 10 minutes.\nYou must be on a stone surface or touching a stone\nsurface to use this Tremorsense. The stone can be\nnatural or worked.\nYou can use this Bonus Action a number of times\nequal to your Proficiency Bonus, and you regain all\nexpended uses when you finish a Long Rest."}], "662": [{"name": "Darkvision", "text": "You have Darkvision with a range of\n60 feet."}, {"name": "Elven Lineage", "text": "You are part of a lineage that\ngrants you supernatural abilities. Choose a lineage\nfrom the Elven Lineages table. You gain the level 1\nbenefit of that lineage.\nWhen you reach character levels 3 and 5, you\nlearn a higher-level spell, as shown on the table.\nYou always have that spell prepared. You can cast it\nonce without a spell slot, and you regain the ability\nto cast it in that way when you finish a Long Rest.\nYou can also cast the spell using any spell slots you\nhave of the appropriate level.\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait\n(choose the ability when you select the lineage)."}, {"name": "Fey Ancestry", "text": "You have Advantage on saving\nthrows you make to avoid or end the Charmed\ncondition."}, {"name": "Keen Senses", "text": "You have proficiency in the Insight,\nPerception, or Survival skill."}, {"name": "Trance", "text": "You don’t need to sleep, and magic can’t\nput you to sleep. You can finish a Long Rest in 4\nhours if you spend those hours in a trancelike meditation, during which you retain consciousness.\nElven Lineages\nLineage Level 1 Level 3 Level 5\nDrow The range ofyour Darkvision increases to 120 feet.\nYou also know the Dancing Lights cantrip.\nFaerie Fire Darkness\nHigh Elf You know the Prestidigitation cantrip. Whenever you\nfinish a Long Rest, you can replace that cantrip with a\ndifferent cantrip from the Wizard spell list.\nDetect Magic Misiv Step\nWood Elf Your Speed increases to 35 feet. You also know the\nDruidcraft cantrip.\nLongstrider Pas-. without Trace"}], "663": [{"name": "Darkvision", "text": "You have Darkvision with a range of\n60 feet."}, {"name": "Gnomish Cunning", "text": "You have Advantage on Intelligence, Wisdom, and Charisma saving throws."}, {"name": "Gnomish Lineage", "text": "You are part of a lineage that\ngrants you supernatural abilities. Choose one of\nthe following options; whichever one you choose,\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait\n(choose the ability when you select the lineage):\nForest Gnome. You know the Minor Illusion cantrip.\nYou also always have the Speak with Animals spell\nprepared. You can cast it without a spell slot a\nnumber of times equal to your Proficiency Bonus,\nand you regain all expended uses when you finish\na Long Rest. You can also use any spell slots you\nhave to cast the spell.\nRock Gnome. You know the Mending and Prestidigitation cantrips. In addition, you can spend 10\nminutes casting Prestidigitation to create a Tiny\nclockwork device (AC 5,1 HP), such as a toy, fire\nstarter, or music box. When you create the device,\nyou determine its function by choosing one effect\nfrom Prestidigitation; the device produces that\neffect whenever you or another creature takes\na Bonus Action to activate it with a touch. If the\nchosen effect has options within it, you choose\none of those options for the device when you\ncreate it. For example, if you choose the spell’s\nignite-extinguish effect, you determine whether\nthe device ignites or extinguishes fire; the device\ndoesn't do both. You can have three such devices\nin existence at a time, and each falls apart 8 hours\nafter its creation or when you dismantle it with a\ntouch as a Utilize action."}], "664": [{"name": "Giant Ancestry", "text": "You are descended from Giants.\nChoose one of the following benefits—a supernatural boon from your ancestry; you can use the\nchosen benefit a number of times equal to your\nProficiency Bonus, and you regain all expended uses\nwhen you finish a Long Rest:\nCloud’s Jaunt (Cloud Giant). As a Bonus Action,\nyou magically teleport up to 30 feet to an unoccupied space you can see.\nFire’s Burn (Fire Giant). When you hit a target\nwith an attack roll and deal damage to it, you can\nalso deal ldlO Fire damage to that target.\nFrost’s Chill (Frost Giant). When you hit a target\nwith an attack roll and deal damage to it, you\ncan also deal ld6 Cold damage to that target and\nreduce its Speed by 10 feet until the start of your\nnext turn.\nHill’s Tumble (Hill Giant). When you hit a Large\nor smaller creature with an attack roll and deal\ndamage to it, you can give that target the Prone\ncondition.\nStone’s Endurance (Stone Giant). When you take\ndamage, you can take a Reaction to roll ldl2. Add\nyour Constitution modifier to the number rolled\nand reduce the damage by that total.\nStorm’s Thunder (Storm Giant). When you take\ndamage from a creature within 60 feet of you,\nyou can take a Reaction to deal ld8 Thunder damage to that creature."}, {"name": "Large Form", "text": "Starting at character level 5, you\ncan change your size to Large as a Bonus Action if\nyou’re in a big enough space. This transformation\nlasts for 10 minutes or until you end it (no action\nrequired). For that duration, you have Advantage\non Strength checks, and your Speed increases by 10\nfeet. Once you use this trait, you can’t use it again\nuntil you finish a Long Rest."}, {"name": "Powerful Build", "text": "You have Advantage on any saving throw you make to end the Grappled condition.\nYou also count as one size larger when determining\nyour carrying capacity."}], "665": [{"name": "Brave", "text": "You have Advantage on saving throws you\nmake to avoid or end the Frightened condition."}, {"name": "Halfling Nimbleness", "text": "You can move through the\nspace of any creature that is a size larger than you,\nbut you can’t stop in the same space."}, {"name": "Luck", "text": "When you roll a 1 on the d20 of a D20 Test,\nyou can reroll the die, and you must use the new\nroll."}, {"name": "Naturally Stealthy", "text": "You can take the Hide action\neven when you are obscured only by a creature that\nis at least one size larger than you."}], "666": [{"name": "Resourceful", "text": "You gain Heroic Inspiration whenever you finish a Long Rest."}, {"name": "Skillful", "text": "You gain proficiency in one skill of your\nchoice."}, {"name": "Versatile", "text": "You gain an Origin feat of your choice\n(see chapter 5). Skilled is recommended."}], "667": [{"name": "Adrenaline Rush", "text": "You can take the Dash action as\na Bonus Action. When you do so, you gain a number\nof Temporary Hit Points equal to your Proficiency\nBonus.\nYou can use this trait a number of times equal\nto your Proficiency Bonus, and you regain all expended uses when you finish a Short or Long Rest."}, {"name": "Darkvision", "text": "You have Darkvision with a range of\n120 feet."}, {"name": "Relentless Endurance", "text": "When you are reduced to 0\nHit Points but not killed outright, you can drop to 1\nHit Point instead. Once you use this trait, you can’t\ndo so again until you finish a Long Rest."}], "668": [{"name": "Darkvision", "text": "You have Darkvision with a range of\n60 feet."}, {"name": "Fiendish Legacy", "text": "You are the recipient of a legacy\nthat grants you supernatural abilities. Choose a legacy from the Fiendish Legacies table. You gain the\nlevel 1 benefit of the chosen legacy.\nFiendish Legacies\nLegacy Level 1\nAbyssal You have Resistance to Poison damage.\nYou also know the Poison Spray cantrip.\nChthonic You have Resistance to Necrotic damage.\nYou also know the Chill Touch cantrip.\nInfernal You have Resistance to Fire damage.\nYou also know the Fire Bolt cantrip.\nWhen you reach character levels 3 and 5, you\nlearn a higher-level spell, as shown on the table.\nYou always have that spell prepared. You can cast it\nonce without a spell slot, and you regain the ability\nto cast it in that way when you finish a Long Rest.\nYou can also cast the spell using any spell slots you\nhave of the appropriate level.\nIntelligence, Wisdom, or Charisma is your spellcasting ability for the spells you cast with this trait\n(choose the ability when you select the legacy)."}, {"name": "Otherworldly Presence", "text": "You know the Thaumaturgy cantrip. When you cast it with this trait, the\nspell uses the same spellcasting ability you use for\nyour Fiendish Legacy trait.\nLevel 3\nRay ofSickness\nFalse Life\nHellish Rebuke\nLevel 5\nHold Person\nRay ofEnfeeblement\nDarkness"}]};
